        )
    annotations: dict[str, dict[str, Any]] = {}
    unresolved_candidates: list[dict[str, Any]] = []

    for fill in fills:
        fill_id = text(fill.get("standard_record_id"))
        fill_time = parse_time(fill.get("fill_time_utc"))
        symbol = text(fill.get("symbol_standard"))
        candidates: list[tuple[dict[str, Any], str]] = []
        for summary in summaries:
            if summary["symbol"] != symbol:
                continue
            if summary["open_time"] <= fill_time <= summary["close_time"]:
                candidates.append((summary, summary_action(summary, fill)))
        chosen: tuple[dict[str, Any], str] | None = None
        basis = "NO_SUMMARY_INTERVAL_CANDIDATE"
        if len(candidates) == 1:
            chosen = candidates[0]
            basis = "唯一symbol+摘要时间区间候选"
        elif (
            len(candidates) == 2
            and {action for _, action in candidates} == {"OPEN", "CLOSE"}
        ):
            target_action = (
                "CLOSE"
                if order_pnl[text(fill.get("order_id")) or ""] != 0
                else "OPEN"
            )
            matching = [
                candidate
                for candidate in candidates
                if candidate[1] == target_action
            ]
            if len(matching) == 1:
                chosen = matching[0]
                basis = (
                    "同symbol多空摘要重叠；Order已实现盈亏"
                    + ("非0选择减仓侧" if target_action == "CLOSE" else "为0选择增仓侧")
