    .filter((row) => clean(row["T/U编号"]) === oldId)
    .sort(
      (left, right) =>
        timeText(left["节点时间"]).localeCompare(timeText(right["节点时间"])) ||
        clean(left["对应正式委托"]).localeCompare(
          clean(right["对应正式委托"]),
        ),
    );
  let addIndex = 0;
  let reduceIndex = 0;
  const actions = [];
  for (const node of nodes) {
    const nodeType = clean(node["节点类型"]);
    if (nodeType.endsWith("次成功加仓")) addIndex += 1;
    if (nodeType === "实际部分减仓") reduceIndex += 1;
    const actionType =
      nodeType === "正式首仓成交"
        ? "正式首仓"
        : nodeType === "实际部分减仓"
          ? `第${reduceIndex}次实际减仓`
          : `第${addIndex}次成功加仓`;
    const orderId = clean(node["对应正式委托"]);
    const order = orderById.get(orderId);
    const orderFills = fillsByOrder.get(orderId) ?? [];
    const chain = chainByOrder.get(`${newId}|${orderId}`);
    if (!order) errors.push(`${newId} 动作订单 ${orderId} 不在M1 Order归属表`);
    if (!chain && newId === "T001") {
      warnings.push(
        "T001沿用空行为证据规则：正式动作由M1 Order/Fill及现有技术阶梯交叉确认，不补写技术_完整操作链。",
      );
    } else if (!chain) {
      errors.push(`${newId} 动作订单 ${orderId} 不在技术_完整操作链`);
    }
    if (
      order &&
      clean(order["新人工复盘编号"]) !== newId
    ) {
      errors.push(
        `${newId} 动作订单 ${orderId} 的M1新编号为 ${clean(order["新人工复盘编号"])}`,
      );
    }
    const fillQuantity = orderFills.reduce(
      (sum, fill) => sum + num(fill.fill_quantity),
      0,
    );
    const fillQuote = orderFills.reduce(
      (sum, fill) => sum + num(fill.fill_quantity) * num(fill.fill_price),
      0,
    );
    const fillAverage = fillQuantity ? fillQuote / fillQuantity : 0;
    const lastFill = orderFills
      .map((fill) => timeText(fill.fill_time_beijing))
      .sort()
      .at(-1);
    if (!almostEqual(fillQuantity, node["本次成交数量"])) {
      errors.push(`${newId} 订单 ${orderId} Fill数量与06B节点不一致`);
    }
    if (!almostEqual(fillAverage, node["本次成交均价"], 1e-6)) {
      errors.push(`${newId} 订单 ${orderId} Fill加权均价与06B节点不一致`);
    }
    if (lastFill !== timeText(node["节点时间"])) {
      errors.push(
        `${newId} 订单 ${orderId} 完成时间不一致：${lastFill} / ${timeText(node["节点时间"])}`,
      );
    }
    if (chain) {
      if (!almostEqual(chain["仓位变化前"], node["节点前实际持仓数量"])) {
        errors.push(`${newId} 订单 ${orderId} 动作前持仓与完整操作链不一致`);
      }
      if (!almostEqual(chain["仓位变化后"], node["节点后实际持仓数量"])) {
        errors.push(`${newId} 订单 ${orderId} 动作后持仓与完整操作链不一致`);
      }
      if (!almostEqual(chain["实际成交数量"], node["本次成交数量"])) {
        errors.push(`${newId} 订单 ${orderId} 成交数量与完整操作链不一致`);
      }
    }

const cycle = cycleByNewId.get(sampleId);
if (!cycle) {
  errors.push(`${sampleId} 缺少M1周期主表记录`);
} else if (
  !almostEqual(maximumPosition, cycle.maximum_absolute_position, 1e-8)
) {
  errors.push(`${sampleId} 最大持仓与M1周期主表不一致`);
}
const reductionThenAdd = reductions.some((reduction) =>
  adds.some(
    (add) =>
      add.completionTimeBeijing > reduction.completionTimeBeijing,
  ),
);
audit.push({
  sampleId,
  formalOpenCount: opens.length,
  successfulAddCount: adds.length,
  partialReductionCount: reductions.length,
  displayNodeCount: actions.length,
  withinTenRowCapacity: actions.length <= 10,
  positionContinuity: continuityErrors.length ? "不通过" : "通过",
  continuityErrors,
  maximumPosition: String(maximumPosition),
  maximumPositionAverage: maxAction?.remainingPositionAverage ?? "",
  m1MaximumPosition: clean(cycle?.maximum_absolute_position),
  reductionThenAdd: reductionThenAdd ? "是" : "否",
});

const result = {
  task: "M4-F2 十笔增强原型仓位链连续性重建",
  samples,
  oldToNew,
  rollingOffsetsInheritedFromCurrentWorkbook: offsets,
  actionAudit: audit,
  actionsBySample,
  evidenceRows,
  totals: {
    formalOpenCount: audit.reduce((sum, item) => sum + item.formalOpenCount, 0),
    successfulAddCount: audit.reduce(
      (sum, item) => sum + item.successfulAddCount,
      0,
    ),
    partialReductionCount: audit.reduce(
      (sum, item) => sum + item.partialReductionCount,
      0,
    ),
    displayNodeCount: audit.reduce(
      (sum, item) => sum + item.displayNodeCount,
      0,
    ),
    reductionThenAddTradeCount: audit.filter(
      (item) => item.reductionThenAdd === "是",
    ).length,
  },
  t049: {
    chain: t049Chain,
    nineToFiveToSevenClosed: t049Closed,
  },
  stopConditionTriggered: errors.length > 0,
  errors,
  warnings,
};

await fs.writeFile(
  path.join(baseline, "M4-F2_仓位动作重建结果.json"),
  JSON.stringify(result, null, 2),
  "utf8",
);

