const lifecycleWorkbook = sourceWorkbooks.M4_02;
const lifecycleSheet = lifecycleWorkbook.worksheets.getItem("生命周期主表");
const lifecycleValues = lifecycleSheet.getUsedRange().values;
const lifecycleHeaders = headerMap(lifecycleValues[3]);
const lifecycleRows = lifecycleValues.slice(4);
assert(lifecycleRows.length === 543, "Lifecycle table is not 543 rows");
const lifecycleRecords = lifecycleRows.map((row) => {
  const conditionId = String(
    getCellValue(row, lifecycleHeaders, "condition_record_id"),
  );
  const evidence = directEvidence.get(conditionId);
  assert(evidence, `Missing direct evidence for ${conditionId}`);
  assert(
    evidence.status === getCellValue(row, lifecycleHeaders, "status"),
    `Status mismatch for ${conditionId}`,
  );
  assert(
    evidence.symbol === getCellValue(row, lifecycleHeaders, "symbol"),
    `Symbol mismatch for ${conditionId}`,
  );
  return {
    row,
    conditionId,
    algorithmId: String(
      getCellValue(row, lifecycleHeaders, "algorithm_id"),
    ),
    status: getCellValue(row, lifecycleHeaders, "status"),
    method: getCellValue(row, lifecycleHeaders, "cycle_link_method"),
    positionCycleId: getCellValue(
      row,
      lifecycleHeaders,
      "position_cycle_id",
    ),
    beforeReduce: getCellValue(row, lifecycleHeaders, "reduce_only"),
    beforeMaker: getCellValue(row, lifecycleHeaders, "maker_only"),
    beforeCategory: getCellValue(row, lifecycleHeaders, "证据来源类别"),
    evidence,
  };
});
assert(
  new Set(lifecycleRecords.map((item) => item.algorithmId)).size === 543,
  "algorithm_id uniqueness changed",
);
const statusCounts = countBy(lifecycleRecords.map((item) => item.status));
const methodCounts = countBy(lifecycleRecords.map((item) => item.method));
assert(
  statusCounts.get("已完成") === 46 &&
    statusCounts.get("已取消") === 382 &&
    statusCounts.get("已过期") === 115,
  "Lifecycle status baseline mismatch",
);
assert(
  methodCounts.get("DIRECT_ORDER") === 46 &&
    methodCounts.get("STRONG_CONTEXT") === 457 &&
    methodCounts.get("CANDIDATE") === 40,
  "Cycle-link baseline mismatch",
);
assert(
  lifecycleRecords.filter((item) => item.method === "CANDIDATE")
    .every((item) => !item.positionCycleId),
  "A CANDIDATE row is formally assigned",
);
const reduceIndex = lifecycleHeaders.get("reduce_only");
const makerIndex = lifecycleHeaders.get("maker_only");
const lifecycleCategoryIndex = lifecycleHeaders.get("证据来源类别");
setColumn(
  lifecycleSheet,
  4,
  reduceIndex,
  lifecycleRecords.map((item) => item.evidence.reduceOnly),
);
setColumn(
  lifecycleSheet,
  4,
  makerIndex,
  lifecycleRecords.map((item) => item.evidence.makerOnly),
);
setColumn(
  lifecycleSheet,
  4,
  lifecycleCategoryIndex,
  lifecycleRecords.map((item) => technicalCategory[item.method]),
);

