for (const record of lifecycle) {
  if (record.cycle_link_method !== "DIRECT_ORDER") {
    const direction =
      record.close_direction === "平多"
        ? "多头"
        : record.close_direction === "平空"
          ? "空头"
          : "";
    const strictCandidates =
      record.created_at && record.terminal_at && direction && record.reduce_only === "是"
        ? cycles.filter(
            (cycle) =>
              cycle.品种 === record.symbol &&
              cycle.方向 === direction &&
              cycle.start &&
              cycle.end &&
              record.created_at <= cycle.end &&
              record.terminal_at >= cycle.start,
          )
        : [];
    record.候选周期ID = strictCandidates.map((row) => row.position_cycle_id).join("|");
    if (strictCandidates.length === 1) {
      record.position_cycle_id = strictCandidates[0].position_cycle_id;
      record.cycle_link_method = "STRONG_CONTEXT";
      record.cycle_link_confidence =
        "严格上下文：品种、平仓方向、reduce_only、生命周期与持仓交集、唯一周期、条件方向及触发字段均无冲突";
    } else if (strictCandidates.length > 1) {
      record.cycle_link_method = "CANDIDATE";
      record.cycle_link_confidence = "存在多周期竞争，仅保留候选，不写入正式position_cycle_id";
    } else {
      record.cycle_link_method = "UNLINKED";
      record.cycle_link_confidence =
        record.reduce_only === "是"
          ? "无满足全部严格条件的仓位周期"
          : "关键字段不足或reduce_only条件不满足";
    }
  }
  const cycle = record.position_cycle_id ? cycleById.get(record.position_cycle_id) : null;
  if (cycle) {
    record.旧技术展示编号 = cycle.旧技术展示编号 || "";
    record.新人工复盘编号 = cycle.新人工复盘编号 || "";
    record.交易来源分类 = cycle.交易来源分类 || "";
    record.个人行为分析资格 = cycle.后续个人行为分析资格 || "";
    record.资金轨迹资格 = cycle.后续资金轨迹资格 || "";
  }
  record.证据来源类别 = evidenceCategory(record);
}

const intervalEvidence = [];
const coverage = cycles
  .filter((cycle) => cycle.交易来源分类 === "个人主动")
  .map((cycle) => {
    const conditions = linkedByCycle.get(cycle.position_cycle_id) || [];
    const clipped = conditions
      .map((condition) => {
        const interval = clipInterval(
          condition.created_at,
          condition.terminal_at,
          cycle.start,
          cycle.end,
        );
        if (!interval) return null;
        const item = {
          position_cycle_id: cycle.position_cycle_id,
          新T编号: cycle.新人工复盘编号,
          algorithm_id: condition.algorithm_id,
          条件作用类别: condition.condition_role,
          覆盖起点: interval[0],
          覆盖终点: interval[1],
          覆盖秒数: secondsBetween(interval[0], interval[1]),
          关联等级: condition.cycle_link_method,
          证据来源类别:
            condition.cycle_link_method === "DIRECT_ORDER"
              ? "基础订单直接关联"
              : "严格时间与仓位关系计算",
        };
        intervalEvidence.push(item);
        return { condition, interval };
      })
      .filter(Boolean);
    const stop = clipped.filter((row) => row.condition.condition_role === "止损型");
    const take = clipped.filter((row) => row.condition.condition_role === "止盈型");
    const stopIntervals = stop.map((row) => row.interval);
    const takeIntervals = take.map((row) => row.interval);
    const allIntervals = clipped.map((row) => row.interval);
    const duration = secondsBetween(cycle.start, cycle.end) || 0;
    const stopCoverage = totalIntervalSeconds(stopIntervals);
    const takeCoverage = totalIntervalSeconds(takeIntervals);
    const allCoverage = totalIntervalSeconds(allIntervals);
    const firstStop = stop
      .map((row) => row.condition.created_at)
      .filter(Boolean)
      .sort((a, b) => a - b)[0];
    const activeAtEnd = stop.some(
      (row) =>
        row.condition.created_at <= cycle.end && row.condition.terminal_at >= cycle.end,
    );
    return {
      position_cycle_id: cycle.position_cycle_id,
      新T编号: cycle.新人工复盘编号,
      品种: cycle.品种,
      方向: cycle.方向,
      持仓开始: cycle.start,
      持仓结束: cycle.end,
      持仓秒数: duration,
      止损条件单数量: conditions.filter((row) => row.condition_role === "止损型").length,
      止盈条件单数量: conditions.filter((row) => row.condition_role === "止盈型").length,
      条件委托总数: conditions.length,
      已完成数量: conditions.filter((row) => row.status === "已完成").length,
      已取消数量: conditions.filter((row) => row.status === "已取消").length,
      已过期数量: conditions.filter((row) => row.status === "已过期").length,
      首次止损创建时间: firstStop || null,
      首次止损延迟秒数: firstStop
        ? Math.max(0, Math.round((firstStop - cycle.start) / 1000))
        : null,
      止损覆盖总秒数: stopCoverage,
      止损未覆盖总秒数: Math.max(0, duration - stopCoverage),
      止损覆盖率: duration ? stopCoverage / duration : 0,
      最大止损空档秒数: maxGapSeconds(cycle.start, cycle.end, stopIntervals),
      止盈覆盖总秒数: takeCoverage,
      止盈覆盖率_非风险保护率: duration ? takeCoverage / duration : 0,
      全部条件委托覆盖秒数: allCoverage,
      全部条件委托覆盖率: duration ? allCoverage / duration : 0,
      持仓结束时是否仍存在有效止损: activeAtEnd ? "是" : "否",
      证据完整性: conditions.length
        ? "已按正式关联记录计算；CANDIDATE/UNLINKED不计入覆盖"
        : "无正式关联条件委托（不代表未设置）",
      可否进入行为分析: "是（仅允许客观时序事实，不新增心理标签）",
      计算证据等级: "严格时间与仓位关系计算",
    };
  })
  .sort((a, b) => a.新T编号.localeCompare(b.新T编号));

const p3 = await importWorkbook(sources.p3_main);
const sheetInspect = await p3.inspect({ kind: "sheet", include: "id,name", maxChars: 20000 });
const sheetNames = sheetNamesFromInspect(sheetInspect.ndjson);
const candidates = [];

for (const sheetName of sheetNames) {
  const sheet = p3.worksheets.getItem(sheetName);
  const used = sheet.getUsedRange(true);
  if (!used) continue;
  const values = used.values ?? [];
  let headerIndex = -1;
  for (let rowIndex = 0; rowIndex < Math.min(values.length, 30); rowIndex += 1) {
    const cells = (values[rowIndex] ?? []).map((value) => String(value ?? "").trim());
    if (
      cells.includes("内部展示编号")
      && cells.includes("条件委托列表时间")
      && cells.includes("页面状态")
    ) {
      headerIndex = rowIndex;
      break;
    }
  }
  if (headerIndex < 0) continue;
  const headers = values[headerIndex].map((value) => String(value ?? "").trim());
  const idColumn = headers.indexOf("内部展示编号");
  const statusColumn = headers.indexOf("页面状态");
  const dataRows = values
    .slice(headerIndex + 1)
    .filter((row) => /^COND-\d{4}$/.test(String(row?.[idColumn] ?? "").trim()));
  const statusCounts = {};
  for (const row of dataRows) {
    const status = String(row[statusColumn] ?? "").trim() || "空值";
    statusCounts[status] = (statusCounts[status] ?? 0) + 1;
  }
  candidates.push({ sheetName, headerIndex, headers, dataRows, statusCounts, usedRows: values.length, usedCols: Math.max(...values.map((row) => row.length), 0) });
}

