def condition_candidate_cycles(condition: dict, cycle_basics: list[dict]) -> list[dict]:
    if condition["status"] == "已完成" or condition["quantity_decimal"] <= 0:
        return []
    list_time = parse_bj(condition["list_time"])
    if not list_time:
        return []
    expected_direction = {"平多": "多头", "平空": "空头"}.get(condition["close_direction"])
    if not expected_direction:
        return []
    candidates = []
    for cycle in cycle_basics:
        if cycle["symbol"] != condition["symbol"] or cycle["direction"] != expected_direction:
            continue
        start = parse_bj(cycle["start_time"])
        end = parse_bj(cycle["end_time"])
        if not start or not end or not (start <= list_time <= end):
            continue
        if condition["quantity_decimal"] > d(cycle["maximum_position"]):
            continue
        if condition["reduce_only"] not in {"是", "未记录", ""}:
            continue
        candidates.append(cycle)
    return candidates

