const requirements = [];
for (const [comboKey, comboStages] of [...comboMap.entries()].sort()) {
  const [symbol, date] = comboKey.split("|");
  const dayStart = Date.parse(`${date}T00:00:00.000Z`);
  const dayEnd = dayStart + DAY_MS;
  for (const type of ["markPriceKlines", "klines", "aggTrades"]) {
    const archive = archiveInfo(symbol, date, type);
    const head = type === "aggTrades"
      ? h0dHeadByKey.get(`${type}|${symbol}|${date}`) ?? h0aHeadByKey.get(`${type}|${symbol}|${date}`)
      : h0aHeadByKey.get(`${type}|${symbol}|${date}`);
    const stageIds = uniqueSorted(comboStages.map((stage) => stage.stage_id));
    const cycleIds = uniqueSorted(comboStages.map((stage) => stage.position_cycle_id));
    const tIds = uniqueSorted(comboStages.map((stage) => stage.new_t_id));
    const earliest = Math.min(...comboStages.map((stage) => Math.max(stage.stage_start_ms, dayStart)));
    const latestExclusive = Math.max(...comboStages.map((stage) => Math.min(stage.stage_end_ms, dayEnd)));
    const boundaryMinutes = new Set();
    for (const stage of comboStages) {
      if (stage.stage_start_ms >= dayStart && stage.stage_start_ms < dayEnd) {
        boundaryMinutes.add(Math.floor(stage.stage_start_ms / MINUTE_MS) * MINUTE_MS);
      }
      if (stage.stage_end_ms > dayStart && stage.stage_end_ms < dayEnd) {
        boundaryMinutes.add(Math.floor((stage.stage_end_ms - 1) / MINUTE_MS) * MINUTE_MS);
      }
    }
