  let group = groups.at(-1);
  if (!group || group.time_ms !== fill.fill_time_ms) {
    group = { time_ms: fill.fill_time_ms, fills: [] };
    groups.push(group);
  }
  group.fills.push(fill);
}
let cycleExcluded = 0;
for (const group of groups) {
  group.fills.forEach((fill, index) => {
    fill.sequence_within_same_ms = index + 1;
  });
  if (group.fills.length > 1) {
    const intermediate = group.fills.length - 1;
    cycleExcluded += intermediate;
    zeroDurationIntermediateExcluded += intermediate;
    actualZeroIntermediateStates += group.fills.slice(0, -1).filter((fill) => fill.position_after === "0").length;
    sameMsGroups.push({
      position_cycle_id: frozen.position_cycle_id,
      new_t_id: frozen.new_t_id,
      symbol: frozen.symbol,
      group_id: group.fills[0].same_ms_group_id,
      fill_time_ms: group.time_ms,
      fill_time_utc: utcIso(group.time_ms),
      fill_count: group.fills.length,
      trade_ids_in_order: group.fills.map((fill) => fill.trade_id),
      order_ids_in_order: group.fills.map((fill) => fill.order_id),
      position_before_group: group.fills[0].position_before,
      position_after_group: group.fills.at(-1).position_after,
      intermediate_states_excluded: intermediate,
      intermediate_zero_position_states: group.fills.slice(0, -1).filter((fill) => fill.position_after === "0").length,
      sequence_status: "PASS",
    });
  }
}
for (let index = 0; index < groups.length; index += 1) {
  const group = groups[index];
  if (group.fills.slice(0, -1).some((fill) => fill.position_after === "0")) {
    assert(group.fills.at(-1).position_after === "0", `same-ms zero-cross/reopen inside cycle ${frozen.new_t_id}`);
  }
  const finalFill = group.fills.at(-1);
