  }
  const next = groups[index + 1];
  assert(next && group.time_ms < next.time_ms, `missing/nonpositive next boundary ${frozen.new_t_id}`);
  const stageNo = stages.filter((stage) => stage.position_cycle_id === frozen.position_cycle_id).length + 1;
  const dateSet = utcDates(group.time_ms, next.time_ms);
