function utcIso(ms) {
  return new Date(ms).toISOString();
}

function bjtText(ms) {
  const iso = new Date(ms + 8 * 3_600_000).toISOString();
  return `${iso.slice(0, 10)} ${iso.slice(11, 23)} +08:00`;
}

function utcDates(startMs, endMsExclusive) {
  const result = [];
  let cursor = Math.floor(startMs / DAY_MS) * DAY_MS;
  const last = Math.floor((endMsExclusive - 1) / DAY_MS) * DAY_MS;
  while (cursor <= last) {
    result.push(utcIso(cursor).slice(0, 10));
    cursor += DAY_MS;
  }
  return result;
}

function uniqueSorted(values, comparator) {
  return [...new Set(values)].sort(comparator);
}

function sha256Text(value) {
  return crypto.createHash("sha256").update(value).digest("hex");
}

function sourceHashForBasename(fileName) {
  const matches = baseline.rows.filter((row) => path.basename(row.relative_path) === fileName);
  assert(matches.length === 1, `source basename ${fileName} matches ${matches.length} baseline files`);
  return matches[0].sha256;
}

function archiveInfo(symbol, date, type) {
  const base = "https://data.binance.vision/data/futures/um/daily";
  if (type === "markPriceKlines") {
    const filename = `${symbol}-1m-${date}.zip`;
    const url = `${base}/markPriceKlines/${symbol}/1m/${filename}`;
    return { filename, url, checksum_url: `${url}.CHECKSUM`, interval: "1m" };
  }
  if (type === "klines") {
    const filename = `${symbol}-1m-${date}.zip`;
    const url = `${base}/klines/${symbol}/1m/${filename}`;
    return { filename, url, checksum_url: `${url}.CHECKSUM`, interval: "1m" };
  }
  const filename = `${symbol}-aggTrades-${date}.zip`;
  const url = `${base}/aggTrades/${symbol}/${filename}`;
  return { filename, url, checksum_url: `${url}.CHECKSUM`, interval: null };
}

