      utc_date: date,
      cycle_count: cycleIds.length,
      stage_count: stageIds.length,
      position_cycle_ids: cycleIds,
      new_t_ids: tIds,
      earliest_needed_ms: earliest,
      earliest_needed_utc: utcIso(earliest),
      latest_needed_exclusive_ms: latestExclusive,
      latest_needed_exclusive_utc: utcIso(latestExclusive),
      boundary_minute_count: boundaryMinutes.size,
