    opening_time: datetime, closing_time: datetime, snapshots: list[dict]
) -> tuple[dict, dict]:
    before = [s for s in snapshots if s["time"] <= opening_time]
    after = [s for s in snapshots if s["time"] > closing_time]
    if not before or not after:
