    return max(before, key=lambda x: x["time"]), min(after, key=lambda x: x["time"])

def event_class(event: dict, current_cycle: str, personal_cycles: set[str], auto_cycles: set[str]) -> str:
    category = str(event.get("canonical_event_category") or "")
    amount = event["_amount"]
    cycles = event["_cycles"]
    if category == "P2P_EVENT" and amount > 0:
        return "外部入金"
    if category in {"SEND_EVENT", "MERCHANT_ACQUIRING"} and amount < 0:
        return "外部出金"
    if category == "SEND_EVENT" and amount == Decimal("642"):
        return "返佣"
    if category in {
        "INTERNAL_TRANSFER_IN", "INTERNAL_TRANSFER_OUT", "OPTIONS_ACCOUNT_TRANSFER",
        "EARN_SUBSCRIPTION_PRINCIPAL", "EARN_REDEMPTION_PRINCIPAL",
        "COPY_PORTFOLIO_CREATE_OR_DEPOSIT", "COPY_PORTFOLIO_WITHDRAW_OR_CLOSE",
    }:
        return "内部钱包划转"
    if category == "COMMISSION_REBATE":
        return "返佣"
    if current_cycle in cycles:
        if category == "REALIZED_PNL":
            return "当前交易盈亏"
        if category == "TRADING_COMMISSION":
            return "当前交易手续费"
        if category == "FUNDING_FEE":
            return "当前交易资金费"
    if cycles & auto_cycles or event.get("project_id") not in (None, ""):
        if category in {"REALIZED_PNL", "TRADING_COMMISSION", "FUNDING_FEE"}:
            return "自动跟单"
    if (cycles & personal_cycles) - {current_cycle}:
        if category in {"REALIZED_PNL", "TRADING_COMMISSION", "FUNDING_FEE"}:
            return "其他个人主动交易"
    return "其他账户事件"


def aggregate_events(events: list[dict], current_cycle: str, personal_cycles: set[str], auto_cycles: set[str]) -> dict:
    result = {
        "外部入金": Decimal("0"),
        "外部出金": Decimal("0"),
        "内部钱包划转": Decimal("0"),
        "当前交易已实现盈亏": Decimal("0"),
        "当前交易手续费": Decimal("0"),
        "当前交易资金费": Decimal("0"),
        "其他个人主动交易影响": Decimal("0"),
        "自动跟单影响": Decimal("0"),
        "返佣": Decimal("0"),
        "其他账户事件": Decimal("0"),
        "合计资金影响": Decimal("0"),
        "事件数量": 0,
        "事件编号": [],
        "分类明细": defaultdict(lambda: {"count": 0, "amount": Decimal("0")}),
    }
    for event in events:
        cls = event_class(event, current_cycle, personal_cycles, auto_cycles)
        amount = event["_amount"]
        result["事件数量"] += 1
        result["事件编号"].append(str(event.get("canonical_economic_event_id") or ""))
        result["分类明细"][cls]["count"] += 1
        result["分类明细"][cls]["amount"] += amount
        if cls == "外部入金":
            result["外部入金"] += amount
        elif cls == "外部出金":
            result["外部出金"] += abs(amount)
        elif cls == "内部钱包划转":
            result["内部钱包划转"] += amount
        elif cls == "当前交易盈亏":
            result["当前交易已实现盈亏"] += amount
        elif cls == "当前交易手续费":
            result["当前交易手续费"] += amount
        elif cls == "当前交易资金费":
            result["当前交易资金费"] += amount
        elif cls == "其他个人主动交易":
            result["其他个人主动交易影响"] += amount
        elif cls == "自动跟单":
            result["自动跟单影响"] += amount
        elif cls == "返佣":
            result["返佣"] += amount
        else:
            result["其他账户事件"] += amount
