def json_default(value: Any) -> Any:
    if isinstance(value, (datetime, date)):
        return value.isoformat()
    if isinstance(value, Decimal):
        return format(value, "f")
    if isinstance(value, Path):
        return str(value)
    return str(value)

def clean_text(value: Any) -> str:
    if value is None:
        return ""
    return unicodedata.normalize("NFKC", str(value)).strip()


def compact_text(value: Any) -> str:
    return re.sub(r"\s+", "", clean_text(value))


def parse_page_time(value: str) -> str:
    value = compact_text(value)
    match = re.search(r"(2026-\d{2}-\d{2})(\d{2}:\d{2}:\d{2})", value)
    if match:
        return f"{match.group(1)} {match.group(2)}"
    return value


def center(item: dict) -> tuple[float, float]:
    return (
        sum(point[0] for point in item["box"]) / 4,
        sum(point[1] for point in item["box"]) / 4,
    )

def normalize_key_piece(value: Any) -> str:
    value = compact_text(value)
    value = value.replace("已完成", "完成").replace("已取消", "取消").replace("已过期", "过期")
    return re.sub(r"[,，.。:：]", "", value)

