    for row in base_rows:
        order = order_by_id.get(clean_text(row["订单号"]))
        if order:
            row["合约"] = clean_text(order.get("symbol"))
            row["合约识别说明"] = "按视觉复核并以相同OrderId的阶段05合约交叉核验"
        else:
            row["合约"] = row["合约_OCR"]
            row["合约识别说明"] = "仅截图"
        expected = int(order.get("fill_count") or 0) if order else 0
        visible = int(row["截图可见Fill行数"])
        row["阶段05完整Fill数"] = expected
        if row.get("视觉复核成交明细"):
            reviewed = clean_text(row["视觉复核成交明细"])
            row["成交明细完整显示"] = (
                "是" if reviewed.startswith("已显示且当前视窗可核对完整") else "否"
            )
            row["成交明细说明"] = (
                f"{reviewed}；OCR检出{visible}行；阶段05结构化Fill共{expected}行"
            )
        else:
            row["成交明细完整显示"] = (
                "是" if visible == expected and expected > 0 else "否"
            )
            row["成交明细说明"] = (
                f"截图可见{visible}行；阶段05结构化Fill共{expected}行"
            )
        row["阶段05_Order找到"] = "是" if order else "否"
        row["阶段05_Fill找到"] = "是" if fills_by_order.get(clean_text(row["订单号"])) else "否"
        result.append(row)
    return result

