def refresh_screenshot_ocr() -> dict:
    """用本地 RapidOCR 生成辅助索引；原图保持不变。"""
    try:
        from rapidocr_onnxruntime import RapidOCR
    except ImportError as exc:
        raise RuntimeError(
            "缺少本地OCR依赖 rapidocr_onnxruntime；"
            "可复用已保留的P0_截图OCR辅助结果.json。"
        ) from exc
    engine = RapidOCR()
    results = []
    image_paths = [
        (category, path)
        for category, directory in SCREENSHOT_DIRS.items()
        for path in sorted(directory.glob("*.png"))
    ]
    started = time.monotonic()
    for index, (category, path) in enumerate(image_paths, start=1):
        raw_result, elapsed = engine(str(path))
        stat = path.stat()
        items = []
        for entry in raw_result or []:
            box, text_value, confidence = entry
            items.append(
                {
                    "box": [[float(point[0]), float(point[1])] for point in box],
                    "text": str(text_value),
                    "confidence": float(confidence),
                }
            )
        results.append(
            {
                "category": category,
                "path": str(path),
                "relative_path": path.relative_to(ROOT).as_posix(),
                "sha256": sha256_file(path),
                "size_bytes": stat.st_size,
                "mtime_ns": stat.st_mtime_ns,
                "mtime_iso": iso_mtime(path),
                "ocr_elapsed": elapsed,
                "items": items,
            }
        )
        print(
            f"OCR {index}/{len(image_paths)} {category} {path.name} "
            f"items={len(items)}",
            flush=True,
        )
    payload = {
        "generated_at_utc": datetime.now(timezone.utc).isoformat(),
        "engine": "rapidocr_onnxruntime（本地离线辅助OCR）",
        "source_rule": "OCR仅作辅助；关键字段仍须回到原图视觉二次核对。",
        "image_count": len(results),
        "elapsed_seconds": round(time.monotonic() - started, 3),
        "results": results,
    }
    write_json(OCR_CACHE, payload)

