def event_position_at(
    formal_orders: list[dict[str, Any]], event_time: datetime | None
) -> str:
    position = "0"
    if event_time is None:
        return position
    for order in sorted(
        formal_orders,
        key=lambda item: parse_dt(item.get("last_fill_time"))
        or datetime.max,
    ):
        fill_time = parse_dt(order.get("last_fill_time"))
        if fill_time is not None and fill_time <= event_time:
            position = plain_decimal(order.get("position_after")) or "0"
    return position


def previous_same_symbol_end(
    cycle: dict[str, Any],
    cycles_by_symbol: dict[str, list[dict[str, Any]]],
) -> datetime | None:
    start = parse_dt(cycle.get("start_time"))
    previous: datetime | None = None
    for other in cycles_by_symbol[text(cycle.get("symbol"))]:
        other_end = parse_dt(other.get("end_time"))
        if other_end is not None and start is not None and other_end <= start:
            if text(other.get("tid")) != text(cycle.get("tid")):
                previous = other_end
    return previous


def connected_pre_open_attempts(
    cycle: dict[str, Any],
    base_orders: list[dict[str, str]],
    cycles_by_symbol: dict[str, list[dict[str, Any]]],
    direct_ids: set[str],
) -> list[dict[str, str]]:
    start = parse_dt(cycle.get("start_time"))
    if start is None:
        return []
    previous_end = previous_same_symbol_end(cycle, cycles_by_symbol)
    candidates: list[dict[str, str]] = []
    for order in base_orders:
        created = parse_dt(order.get("北京时间"))
        ended = parse_dt(order.get("结束或更新时间")) or created
        if (
            order.get("合约") == text(cycle.get("symbol"))
            and normalize_id(order.get("主标识")) not in direct_ids
            and decimal_value(order.get("实际成交数量")) == 0
            and created is not None
            and created <= start
            and (previous_end is None or created >= previous_end)
            and order.get("最终状态", "").upper()
            in {"CANCELED", "CANCELLED", "EXPIRED", "REJECTED"}
        ):
            enriched = dict(order)
            enriched["__created"] = created  # type: ignore[assignment]
            enriched["__ended"] = ended  # type: ignore[assignment]
            candidates.append(enriched)
    candidates.sort(key=lambda row: row["__created"])  # type: ignore[index]
    connected: list[dict[str, str]] = []
    anchor = start
    for order in reversed(candidates):
        ended = order["__ended"]  # type: ignore[index]
        created = order["__created"]  # type: ignore[index]
        gap = anchor - ended if ended <= anchor else timedelta(0)
        if gap <= timedelta(hours=2):
            connected.append(order)
            anchor = min(anchor, created)
        elif connected:
            break
    connected.reverse()
    for order in connected:
        order.pop("__created", None)
        order.pop("__ended", None)
    return connected

def assign_order_relationships(events: list[dict[str, str]]) -> None:
    grouped: dict[tuple[str, str], list[dict[str, str]]] = defaultdict(list)
    for event in events:
        if event["事件大类"] in {"正式成交委托", "未成交基础委托", "平仓后残留基础委托"}:
            grouped[(event["T/U编号"], event["阶段区间"])].append(event)
    for group in grouped.values():
        group.sort(
            key=lambda event: (
                parse_dt(event.get("委托创建时间")) or datetime.max,
                event.get("技术委托编号", ""),
            )
        )
        previous: dict[str, str] | None = None
        for event in group:
            if previous is None:
                event["与上一张委托关系"] = "本区间首张订单级委托"
                event["关系置信度"] = event["关系置信度"] or "A"
                previous = event
                continue
            current_time = parse_dt(event.get("委托创建时间"))
            previous_end = (
                parse_dt(previous.get("委托结束时间"))
                or parse_dt(previous.get("委托创建时间"))
            )
            gap = (
                current_time - previous_end
                if current_time is not None and previous_end is not None
                else timedelta.max
            )
            current_side = normalized_side(event["买卖方向"])
            previous_side = normalized_side(previous["买卖方向"])
            same_side = current_side == previous_side
            changed_price_or_qty = (
                event["委托价格"] != previous["委托价格"]
                or event["委托数量"] != previous["委托数量"]
            )
            prior_canceled = previous["委托状态"] in {
                "已取消",
                "已过期",
                "已拒绝",
            }
            if same_side and changed_price_or_qty and prior_canceled and gap <= timedelta(minutes=30):
                event["与上一张委托关系"] = "高置信疑似撤单后改价/改量重挂"
                event["关系置信度"] = "B"
            elif (
                event["阶段区间"].startswith("A")
                and current_side != previous_side
                and gap <= timedelta(hours=2)
            ):
                event["与上一张委托关系"] = "首仓前方向切换"
                event["关系置信度"] = "B"
            elif gap <= timedelta(hours=2):
                event["与上一张委托关系"] = "时间相邻，可能属于连续操作"
                event["关系置信度"] = "C"
                event["是否需要用户人工确认"] = "是"
            else:
                event["与上一张委托关系"] = "无可确认的上一委托关系"
                event["关系置信度"] = "D"
                event["是否需要用户人工确认"] = "是"
            previous = event

assign_order_relationships(events)
